@startuml

class Department {
  + Name : string
}

class Room {
  + RoomNumber : int
}

class Bed {
  + BedNumber : int
  + Category : string
}

class Category {
  + Price : double
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
}

class Stay {
  + Type : string
  + StartDate : date
  + EndDate : date
}

class Invoice {
  + InvoiceNumber : int
  + TotalAmount : double
  + OutstandingAmount : double
}

class Payment {}

Department "1" -- "*" Room
Room "1" -- "*" Bed
Bed "1" -- "*" Category
Inhabitant "0..*" -- "*" Stay
Stay "1" -- "*" Category
Invoice "1" -- "*" Stay

@enduml

